raw = state.get('entities') or []
if isinstance(raw, str):
    import json
    try:
        raw = json.loads(raw)
    except Exception:
        raw = []
seen = set()
out = []
for e in raw:
    if not isinstance(e, dict):
        continue
    txt = str(e.get('text') or '').strip()
    lbl = str(e.get('label') or e.get('type') or '').strip()
    if not txt or not lbl:
        continue
    tl = txt.lower()
    if tl.endswith('-induced'):
        base = txt[: -len('-induced')].strip()
        if base:
            txt = base
    key = (lbl, txt.lower())
    if key in seen:
        continue
    seen.add(key)
    eid = str(e.get('id') or '').strip() or txt
    out.append({'text': txt, 'id': eid, 'label': lbl})
__result__ = out
